//! The Vital panel (`honeydew_audio::vital`), UIHeight 12 U: Honeydew's own card, a tab strip over pages with the
//! sub-pages picked by param-less lists, one control for every parameter of Vital's engine and its 16 modulation
//! slots. Vital's own interface (Matt Tytel, GPL-3.0-or-later) is drawn with JUCE/OpenGL and cannot run on Android, so
//! this card stands in for it. Generated by `tools/gen_vital_panel.py`: do not edit.

use crate::panels::build::*;
use crate::params::VITAL_MODULE;

const LIST_117: &str = "OSC 1 · OSC 2 · OSC 3 · SAMPLE · SUB";

const LIST_158: &str = "FILTER 1 · FILTER 2";

const LIST_213: &str = concat!("ENV 1 · ENV 2 · ENV 3 · ENV 4 · ENV 5 · ", "ENV 6");

const LIST_342: &str = concat!(
    "LFO 1 · LFO 2 · LFO 3 · LFO 4 · LFO 5 · ",
    "LFO 6 · LFO 7 · LFO 8 · RAND 1 · RAND 2 · ",
    "RAND 3 · RAND 4"
);

const LIST_460: &str = concat!(
    "CHORUS · COMP · DELAY · DISTORT · EQ · ",
    "FILTER · FLANGER · PHASER · REVERB"
);

const LIST_465: &str = "MOD 1-4 · MOD 5-8 · MOD 9-12 · MOD 13-16";

/// The index of the param named `name` in the module's table.
fn ix(name: &str) -> usize {
    VITAL_MODULE
        .params
        .iter()
        .position(|p| p.name == name)
        .unwrap_or_else(|| panic!("Vital has no param {name}"))
}

pub fn panel() -> Option<Panel> {
    Some(Panel::new(vstack([
        tabs(1, "OSC · FILTER · ENV · LFO · FX · MOD · VOICE").h(Size::U(1.25)),
        hstack([
            vstack([list(117, LIST_117, Bar::Right)]).w(Size::U(2.4)),
            osc_1().show(Show::Setting(117, 0)),
            osc_2().show(Show::Setting(117, 1)),
            osc_3().show(Show::Setting(117, 2)),
            sample().show(Show::Setting(117, 3)),
            sub().show(Show::Setting(117, 4)),
        ])
        .show(Show::Tab(0)),
        hstack([
            vstack([list(158, LIST_158, Bar::Right)]).w(Size::U(2.4)),
            filter_1().show(Show::Setting(158, 0)),
            filter_2().show(Show::Setting(158, 1)),
        ])
        .show(Show::Tab(1)),
        hstack([
            vstack([list(213, LIST_213, Bar::Right)]).w(Size::U(2.4)),
            envelope_1().show(Show::Setting(213, 0)),
            envelope_2().show(Show::Setting(213, 1)),
            envelope_3().show(Show::Setting(213, 2)),
            envelope_4().show(Show::Setting(213, 3)),
            envelope_5().show(Show::Setting(213, 4)),
            envelope_6().show(Show::Setting(213, 5)),
        ])
        .show(Show::Tab(2)),
        hstack([
            vstack([list(342, LIST_342, Bar::Right)]).w(Size::U(2.4)),
            lfo_1().show(Show::Setting(342, 0)),
            lfo_2().show(Show::Setting(342, 1)),
            lfo_3().show(Show::Setting(342, 2)),
            lfo_4().show(Show::Setting(342, 3)),
            lfo_5().show(Show::Setting(342, 4)),
            lfo_6().show(Show::Setting(342, 5)),
            lfo_7().show(Show::Setting(342, 6)),
            lfo_8().show(Show::Setting(342, 7)),
            random_1().show(Show::Setting(342, 8)),
            random_2().show(Show::Setting(342, 9)),
            random_3().show(Show::Setting(342, 10)),
            random_4().show(Show::Setting(342, 11)),
        ])
        .show(Show::Tab(3)),
        hstack([
            vstack([list(460, LIST_460, Bar::Right)]).w(Size::U(2.4)),
            chorus().show(Show::Setting(460, 0)),
            compressor().show(Show::Setting(460, 1)),
            delay().show(Show::Setting(460, 2)),
            distortion().show(Show::Setting(460, 3)),
            eq().show(Show::Setting(460, 4)),
            filter_fx().show(Show::Setting(460, 5)),
            flanger().show(Show::Setting(460, 6)),
            phaser().show(Show::Setting(460, 7)),
            reverb().show(Show::Setting(460, 8)),
        ])
        .show(Show::Tab(4)),
        vstack([
            hstack([
                knob(461, "Macro 1").p(ix("Macro 1")),
                knob(462, "Macro 2").p(ix("Macro 2")),
                knob(463, "Macro 3").p(ix("Macro 3")),
                knob(464, "Macro 4").p(ix("Macro 4")),
            ])
            .h(Size::U(2.3)),
            hstack([
                vstack([list(465, LIST_465, Bar::Right)]).w(Size::U(2.4)),
                modulation_1().show(Show::Setting(465, 0)),
                modulation_2().show(Show::Setting(465, 1)),
                modulation_3().show(Show::Setting(465, 2)),
                modulation_4().show(Show::Setting(465, 3)),
            ]),
        ])
        .show(Show::Tab(5)),
        voice().show(Show::Tab(6)),
    ])))
}

